function nextTask19(today,nodes){let s=S();if(s.stage>=2&&s.stage<=4){for(let d=s.day;d<=(s.stage===4?28:14);d++){let t=Schedule.tasks(s,d).find(t=>!t.done);if(t)return {title:t.title,date:Schedule.date(s,d),sub:(t.hint||'请按研究安排完成。')+' '+regimen19(s,d),action:t.action,value:t.value}}}if(s.stage===5&&s.followNode==='postop'&&!evalDone19('postop-'+(s.postopMonth||6)))return nodes.find(n=>n.title==='术后'+(s.postopMonth||6)+'个月综合评估');return nodes.find(n=>n.current&&!n.done)||nodes.find(n=>!n.done&&n.date>=today)}
