actions.push19=()=>{let host=$('#patientPhone');host.querySelector('.push19')?.remove();let box=document.createElement('section');box.className='push19 notification-shade20';box.setAttribute('role','dialog');box.setAttribute('aria-label','模拟手机消息通知');let date=nowStudy(),dt=new Date(date+'T12:00:00');box.innerHTML=`<div class="shade-status20"><span>中国移动</span><span>▮▮▮　◔　▰</span></div><div class="shade-clock20"><b>08:00</b><span>${dt.getMonth()+1}月${dt.getDate()}日　${['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][dt.getDay()]}</span></div><small class="shade-caption20">消息通知 · 演示</small><button class="system-notification20" data-action="openPush19" aria-label="橙欣健康通知，查看今日安排"><img src="assets/cx-app-icon.png" alt="橙欣健康app图标"><span class="notification-body20"><span class="notification-meta20"><b>橙欣健康</b><time>08:00</time><span>⌄</span></span><span class="notification-text20">范照青主任提醒您：${esc(pushText19())}</span></span></button>${btn('返回应用','dismissPush19','','shade-close20')}`;host.append(box)};
