const draw20base=drawBatch;drawBatch=()=>{for(let r of V17.batch)if(r.sample&&r.recognizedDate20===undefined)r.recognizedDate20=r.examDate||'';draw20base();let sh=$('#patientModal .sheet'),area=sh?.querySelector('.quality19');if(!area)return;let items=[...area.querySelectorAll('.quality-item')];items.forEach((item,i)=>{let date=sh.querySelector('[name="batchDate'+i+'"]')?.closest('label');if(!date)return;let r=V17.batch[i],q=quality19(r),status=item.querySelector('p');item.querySelector('b')?.remove();if(status){status.className='report-status20 '+(q.status==='通过'?'quality-ok':'quality-error');status.textContent=qualityLabels20[q.status]||q.status;if(issues19[q.status])status.insertAdjacentHTML('afterend','<small class="report-fix20">'+esc(issues19[q.status])+'</small>')}let sel=item.querySelector('[name="qualityCase'+i+'"]');if(sel){let detail=document.createElement('details');detail.className='quality-demo20';detail.innerHTML='<summary>切换演示核验结果</summary>';detail.append(sel.closest('label'));item.append(detail)}item.classList.add('report-validation20');date.after(item);if(q.status==='日期不符'&&r.recognizedDate20)item.insertAdjacentHTML('afterbegin','<small>报告检查日期：'+esc(r.recognizedDate20)+'</small>')});if(V17.qualityNotice){let msg=document.createElement('p');msg.className='quality-error';msg.textContent=V17.qualityNotice;sh.querySelector('#batchFiles').after(msg)}area.remove();};
