function orderHint21(n){if(n.orders)return n.orders;if(n.title.includes('筛选期'))return '核对既往病理、首次穿刺病理、化验和影像资料；缺失项目按入排审核结果补开。';if(n.title.includes('两周评估'))return '安排第二次穿刺病理（含Ki-67）及EPclin基因检测；核对首次病理用于比较。'+(S().risk==='高危'?'后续治疗前安排20ml科研采血。':'');if(n.title.includes('综合评估'))return 'MRI、CT、B超、血常规、肝肾功能。'+(n.title.includes('C6')?'另安排20ml科研采血及两份QLQ量表。':n.title.includes('6个月')?'另收集两份QLQ量表。':'');if(n.title.includes('手术及'))return '核查术前评估是否齐备；手术后获取手术记录、出院记录和术后病理。';return ''}
const nodes21base=nodes19;nodes19=()=>{let nodes=nodes21base();for(let v of Schedule.visits(S())){let ap=S().appointments?.[v.date],date=ap?.date||v.date;nodes.push({title:'第'+v.n+'次门诊复查',date,sub:'按首次服药日的自然月同日复查；核对身体情况及最新处方。',done:!!S().tasks['visit-'+v.date],current:date===nowStudy(),orders:ap?.demo===false&&ap.checks?.length?'本次已安排：'+ap.checks.join('、')+'。'+(ap.prep||''):'本次需核对并开具化验及影像检查；具体检验项目、影像部位和方式待研究医生按方案确认。',appointment:v.date})}return nodes.sort((a,b)=>a.date.localeCompare(b.date))};
timeline=side=>{let nodes=nodes19(),s=S(),today=s.stage===0?Schedule.addDays(s.firstDose||'2026-06-17',-28):nowStudy(),next=nextTask19(today,nodes);let visitNodes=nodes.filter(n=>orderHint21(n)),current=visitNodes.find(n=>n.current&&!n.done)||visitNodes.find(n=>!n.done&&n.date>=today);return `<div class="hint neutral">预计日期为演示安排，实际以研究团队确认为准。首次服药：${s.firstDose||'待医生确认'}。</div>${next?`<div class="card next19"><small>下一项任务</small><h3>${next.title}</h3><b>${next.date}</b><p>${next.sub}</p>${side==='p'?btn('查看今日安排','pgo','tasks','secondary'):''}</div>`:''}<div class="timeline">${nodes.map(n=>`<div class="timeline-item ${n.done?'done':n.current?'current':''}"><b>${n.title}</b><strong class="date19">${n.date}${n.done?'':' · 预计'}</strong><small>${n.sub}</small>${side==='d'&&orderHint21(n)?`<section class="visit-orders21 ${n===current?'visit-upcoming21':''}"><b>${n===current?'本次 / 下一次门诊开单提示':'该节点检查提示'}</b><p>${esc(orderHint21(n))}</p>${n.appointment?btn('确认或调整检查安排','appointment',n.appointment,'text-btn'):''}</section>`:''}${pill(n.done?'已完成':n.current?'当前阶段':n===next?'下一项任务':'后续安排',n.done?'green':'')}</div>`).join('')}</div>`};

